/// Count comparisons made during execution.
static mut COMPCNT: u64 = 0;

#[inline(always)]
fn cmp(a: i32, b: i32) -> bool {
    unsafe { COMPCNT += 1; }
    a < b
}

// --- ALGORITHM A: Tournament-style min+max finder ---
// Cost: floor(3n/2) - 2 comparisons total. Finds BOTH extremes.
// Does NOT find the median but demonstrates the tournament paradigm.
fn find_min_max(arr: &[i32]) -> ((usize, i32), (usize, i32)) {
    let n = arr.len();
    unsafe { COMPCNT = 0; }

    if n == 1 { return ((0, arr[0]), (0, arr[0])); }
    if n == 2 {
        if cmp(arr[0], arr[1]) { return ((0, arr[0]), (1, arr[1])); }
        else                   { return ((1, arr[1]), (0, arr[0])); }
    }

    let (mut min_idx, mut min_val) = if cmp(arr[0], arr[1]) {(0, arr[0])} else {(1, arr[1])};
    let (mut max_idx, mut max_val) = if cmp(arr[0], arr[1]) {(1, arr[1])} else {(0, arr[0])};

    let start = if n % 2 == 0 { 2 } else { 1 };
    for i in (start..n).step_by(2) {
        let (lo, hi) = if cmp(arr[i], arr[i + 1]) {(i, i + 1)} else {(i + 1, i)};
        if cmp(arr[lo], min_val) { min_idx = lo; min_val = arr[lo]; }
        if cmp(arr[hi], max_val) { max_idx = hi; max_val = arr[hi]; }
    }

    ((min_idx, min_val), (max_idx, max_val))
}

// --- ALGORITHM B: Naive selection -- scan left/right counts ---
// For each element, count how many are smaller and larger.
// Cost: n*(n-1) comparisons. Only good for small n or proof-of-concept.
fn select_median_bubble(arr: &[i32]) -> Option<i32> {
    let n = arr.len();
    let k = n / 2; // target rank (0-indexed: k-th of 0..n-1

    unsafe { COMPCNT = 0; }

    for j in 0..n {
        let mut cnt_less = 0;
        let mut cnt_greater = 0;

        for i in 0..n {
            if i == j { continue; }
            if cmp(arr[i], arr[j]) { cnt_less += 1; }
            else                   { cnt_greater += 1; }
        }

        if cnt_less == k && cnt_greater == k {
            return Some(arr[j]);
        }
    }
    None
}

// --- ALGORITHM C: Quickselect with pivot partitioning ---
// Average: O(n) comparisons, worst case O(n"'^2). Demonstrates O(n) upper bound.
fn quickselect_median(arr: &mut [i32], target_rank: usize) -> Option<i32> {
    unsafe { COMPCNT = 0; }
    inner_quickselect(arr, target_rank)
}

fn inner_quickselect(arr: &mut [i32], target_rank: usize) -> Option<i32> {
    if arr.is_empty() { return None; }
    if arr.len() == 1 { return Some(arr[0]); }

    let mid = arr.len() / 2;
    let pivot = arr[mid];

    let mut left: Vec<i32> = Vec::new();
    let mut right: Vec<i32> = Vec::new();

    for &x in arr.iter() {
        if x != pivot {
            unsafe { COMPCNT += 1; }
            if x < pivot {
                left.push(x);
            } else {
                right.push(x);
            }
        }
    }

    match target_rank.cmp(&left.len()) {
        std::cmp::Ordering::Equal => Some(pivot),
        std::cmp::Ordering::Less => inner_quickselect(&mut left[..], target_rank),
        std::cmp::Ordering::Greater => {
            let eq_count = arr.len() - left.len() - right.len();
            inner_quickselect(&mut right[..], target_rank - left.len() - eq_count)
        }
    }
}

// --- ALGORITHM D: Sort-and-index (proves T(n) <= n log_2 n + O(n)) ---
fn insertion_sort_select_median(arr: &[i32]) -> Option<i32> {
    let n = arr.len();
    let mut sorted = arr.to_vec();
    unsafe { COMPCNT = 0; }

    for i in 1..n {
        let key = sorted[i];
        let mut j = i as isize - 1;
        while j >= 0 {
            unsafe { COMPCNT += 1; }
            if sorted[j as usize] > key {
                sorted[(j + 1) as usize] = sorted[j as usize];
                j -= 1;
            } else { break; }
        }
        sorted[(j + 1) as usize] = key;
    }

    Some(sorted[n / 2])
}

