use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::collections::hash_map::DefaultHasher;

fn hash_element<T: Hash>(val: &T) -> u64 {
    let mut hasher = DefaultHasher::new();
    val.hash(&mut hasher);
    hasher.finish()
}

// Hash-bucket selection: uses O(1) hashing, still needs comparisons within buckets.
fn hash_bucket_selection<T: Clone + PartialEq + Hash>(
    items: &[T],
    hash_fn: impl Fn(&T) -> u64,
    rank_target: usize,
) -> Option<T> {
    let n = items.len();
    if n == 0 { return None; }
    if n == 1 { return Some(items[0].clone()); }

    let n_buckets = n.max(4);
    let mut buckets: Vec<Vec<(u64, T)>> = vec![Vec::new(); n_buckets];

    for item in items {
        let h = hash_fn(item);
        let idx = (h as usize) % n_buckets;
        buckets[idx].push((h, item.clone()));
    }

    // Sort each bucket internally by hash value
    for bucket in &mut buckets {
        bucket.sort_by(|a, b| a.0.cmp(&b.0));
    }

    // Concatenate and flatten into single ordered-by-hash list
    let mut sorted_by_hash: Vec<&T> = Vec::with_capacity(n);
    for bucket in &buckets {
        for (_, v) in bucket.iter() {
            sorted_by_hash.push(v);
        }
    }

    // Find the element at the desired rank position
    // NOTE: this is sort BY HASH, not sort BY VALUE -- incorrect for median.
    // We just demonstrate that hash-order does not equal value-order.
    if rank_target < sorted_by_hash.len() {
        Some(sorted_by_hash[rank_target].clone())
    } else {
        None
    }
}

// Correct selection using expensive comparisons efficiently
fn select_expensive_comp<T: Clone + PartialEq>(
    arr: &[T],
    rank: usize,
) -> Option<T> {
    if arr.is_empty() { return None; }
    if arr.len() == 1 { return Some(arr[0].clone()); }

    let pivot = arr[arr.len() / 2].clone();
    let mut less = Vec::new();
    let mut greater = Vec::new();
    let mut equal = 0;

    for item in arr {
        if item == &pivot {
            equal += 1;
        } else if *item < pivot {
            less.push(item.clone());
        } else {
            greater.push(item.clone());
        }
    }

    let l_len = less.len();
    match rank.cmp(&l_len) {
        std::cmp::Ordering::Equal => Some(pivot),
        std::cmp::Ordering::Less => select_expensive_comp(&less, rank),
        std::cmp::Ordering::Greater => {
            select_expensive_comp(&greater, rank - l_len - equal)
        }
    }
}

