fn find_min_max(arr: &[i32]) -> ((usize, i32), (usize, i32)) {
    let n = arr.len();
    unsafe { COMPCNT = 0; }

    if n == 1 { return ((0, arr[0]), (0, arr[0])); }
    if n == 2 {
        if cmp(arr[0], arr[1]) { return ((0, arr[0]), (1, arr[1])); }
        else                   { return ((1, arr[1]), (0, arr[0])); }
    }

    let (mut min_idx, mut min_val) = if cmp(arr[0], arr[1]) {(0, arr[0])} else {(1, arr[1])};
    // Even n: compare first pair; Odd n: both start at arr[0]
    let (start, min_idx, min_val, max_idx, max_val) = if n % 2 == 0 {
        let lo = if cmp(arr[0], arr[1]) {0} else {1};
        let hi = 1 - lo;
        (2, lo, arr[lo], hi, arr[hi])
    } else {
        (1, 0, arr[0], 0, arr[0])
    };
    for i in (start..n).step_by(2) {
        let (lo, hi) = if cmp(arr[i], arr[i + 1]) {(i, i + 1)} else {(i + 1, i)};
        if cmp(arr[lo], min_val) { min_idx = lo; min_val = arr[lo]; }
        if cmp(arr[hi], max_val) { max_idx = hi; max_val = arr[hi]; }
    }

    ((min_idx, min_val), (max_idx, max_val))
}


